// Text of https://tenvor.io/trust (captured 2026-11-20 from the rendered page), word for word; source layout dropped, generated by a one-off script.
import type { SitePage } from "./types";

const page: SitePage = {
  "path": "/trust",
  "metaTitle": "Trust center",
  "kicker": "Trust center",
  "title": "Security and transparency, built into every request.",
  "intro": "How Tenvor protects your requests, your account and your balance, and the controls behind each step.",
  "toc": [],
  "html": "<div><section class=\"tc-hero\"><div class=\"s-row\"><a class=\"s-btn s-btn--accent\" href=\"mailto:security@tenvor.io\">Report a security issue</a><a class=\"s-btn\" href=\"#controls\">Explore our controls</a><a class=\"s-btn\" href=\"/developers#dev-res-h\">See an example receipt</a></div></section><section id=\"commitments\"><p class=\"s-k\">Our commitments</p><h2 class=\"tc-h\">Four things every request can rely on.</h2><div class=\"tc-grid tc-grid--4 reveal\"><div class=\"tc-card\"><p class=\"tc-num\">01 · Billing</p><h3>We count the tokens ourselves</h3><p>A node’s own count is never used to bill you or to pay an operator.</p></div><div class=\"tc-card\"><p class=\"tc-num\">02 · Failures</p><h3>A failed request costs nothing</h3><p>If a request fails on our side after a node has taken it, you are not charged and the node is not paid.</p></div><div class=\"tc-card\"><p class=\"tc-num\">03 · Retention</p><h3>Nothing is retained</h3><p>Requests are never logged or kept. A request’s content and files are erased when it finishes.</p></div><div class=\"tc-card\"><p class=\"tc-num\">04 · Containment</p><h3>The model runs locked down</h3><p>No network, all capabilities dropped, and weights mounted read-only and checked against a pinned hash.</p></div></div></section><section id=\"assurance-status\"><p class=\"s-k\">Security program</p><h2 class=\"tc-h\">Security built into every layer.</h2><div class=\"tc-grid tc-grid--3 reveal\"><a class=\"tc-card tc-st\" href=\"#reviews\"><span class=\"tc-badge tc-badge--done\">In place</span><h3>Internal security reviews</h3><p>Reviews of the whole system, money handling and the live route, July to October 2026.</p></a><a class=\"tc-card tc-st\" href=\"#access\"><span class=\"tc-badge tc-badge--done\">In place</span><h3>Encryption in transit</h3><p>Clients connect over HTTPS. Nodes connect over an encrypted WebSocket.</p></a><a class=\"tc-card tc-st\" href=\"#served\"><span class=\"tc-badge tc-badge--done\">In place</span><h3>Signed releases</h3><p>Serving is switched on by a signed activation that pins the model, runtime and prices by hash.</p></a><a class=\"tc-card tc-st\" href=\"#containment\"><span class=\"tc-badge tc-badge--done\">In place</span><h3>Locked-down model container</h3><p>Rootless, no network, all capabilities dropped, weights read-only and hash-checked.</p></a><a class=\"tc-card tc-st\" href=\"/legal/security\"><span class=\"tc-badge tc-badge--done\">In place</span><h3>Responsible disclosure</h3><p>Report a vulnerability to security@tenvor.io under our Security Policy.</p></a><a class=\"tc-card tc-st\" href=\"#known-limits\"><span class=\"tc-badge tc-badge--prog\">In development</span><h3>Hardware verification</h3><p>Checking node containment independently of the node’s own software.</p></a></div></section><section id=\"controls\"><p class=\"s-k\">Controls</p><h2 class=\"tc-h\">The controls behind the service.</h2><div class=\"tc-grid tc-grid--3 reveal\"><a class=\"tc-card tc-ctl\" href=\"#money\"><h3>Price, charge and payout</h3><ul><li>Prices come from the signed release, not the request</li><li>The worst case is reserved before work starts</li><li>A balance cannot go below zero</li></ul><span class=\"tc-more\">Read more →</span></a><a class=\"tc-card tc-ctl\" href=\"#containment\"><h3>Execution containment</h3><ul><li>Rootless container with no network</li><li>All capabilities dropped, no new privileges</li><li>Weights read-only and hash-checked</li></ul><span class=\"tc-more\">Read more →</span></a><a class=\"tc-card tc-ctl\" href=\"#assurance\"><h3>Checking a result</h3><ul><li>Results signed by the node and bound to the request</li><li>Stale or replayed messages are rejected</li><li>Billing tokens come from our own tokenizer</li></ul><span class=\"tc-more\">Read more →</span></a><a class=\"tc-card tc-ctl\" href=\"#access\"><h3>Accounts and access</h3><ul><li>API keys stored as a hash, shown once</li><li>Rotate or revoke a key at any time</li><li>Another account’s request returns “not found”</li></ul><span class=\"tc-more\">Read more →</span></a><a class=\"tc-card tc-ctl\" href=\"#chat-work\"><h3>Chat &amp; Work</h3><ul><li>Commands run in an E2B sandbox, internet off by default</li><li>Per-task spend cap and 10-minute limit</li><li>Web content labelled untrusted for the model</li></ul><span class=\"tc-more\">Read more →</span></a><a class=\"tc-card tc-ctl\" href=\"#served\"><h3>What is served</h3><ul><li>One model today: <code>chat-35b-moe</code></li><li>A fixed 65,536-token context window</li><li>Serving switched on by a signed activation</li></ul><span class=\"tc-more\">Read more →</span></a></div></section><section id=\"documents\"><p class=\"s-k\">Documents</p><h2 class=\"tc-h\">Policies and terms, all public.</h2><div class=\"tc-docs reveal\"><a class=\"tc-doc\" href=\"/legal/security\"><span><b>Security policy</b><small>What is in scope and how to report</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/privacy\"><span><b>Privacy policy</b><small>What we collect and why</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/subprocessors\"><span><b>Subprocessors</b><small>Third parties that process data</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/acceptable-use\"><span><b>Acceptable use</b><small>What the service may be used for</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/provider-terms\"><span><b>Compute Provider Terms</b><small>Rules node operators agree to</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/public-alpha-risk\"><span><b>Public alpha risk</b><small>What the alpha does not promise</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/legal/terms\"><span><b>Terms of service</b><small>The agreement for using Tenvor</small></span><span aria-hidden=\"true\">→</span></a><a class=\"tc-doc\" href=\"/status\"><span><b>Status</b><small>How incidents are reported</small></span><span aria-hidden=\"true\">→</span></a></div></section><section id=\"faq\"><p class=\"s-k\">FAQ</p><h2 class=\"tc-h\">Common questions.</h2><div class=\"tc-faq\"><details><summary>Can node operators see my prompts?</summary><p>Yes. The operator of a node can read the prompt and output of every request it serves, in plain text. Our Compute Provider Terms forbid them from copying, logging or keeping content. That is a contract, not yet a technical control.</p></details><details><summary>Do you keep my conversations or files?</summary><p>No. Requests are never logged or kept. Conversations, and files a run generates, are erased when the request finishes.</p></details><details><summary>Am I charged if a request fails?</summary><p>Not if it fails on our side. A request you cancel after a node has taken it, or that stops at your own output limit, can be charged for its input and the output it generated.</p></details><details><summary>How is Tenvor’s security reviewed?</summary><p>Reviews are performed internally, covering the whole system, money handling and the live route. Third-party assessments have not been completed to date.</p></details><details><summary>Which models are served?</summary><p>Only <code>chat-35b-moe</code>. The catalog lists three other models with prices, but nothing serves them today.</p></details><details><summary>How do I report a security problem?</summary><p>Write to <a href=\"mailto:security@tenvor.io\">security@tenvor.io</a>. The <a href=\"/legal/security\">security policy</a> says what is in scope and what to expect.</p></details></div></section><section id=\"methodology\"><p class=\"s-k\">Full methodology</p><h2 class=\"tc-h\">How a request is handled, in detail.</h2><nav class=\"tc-toc\" aria-label=\"On this page\"><ol><li><a href=\"#seen\">What we have actually seen</a></li><li><a href=\"#money\">Price, charge and payout</a></li><li><a href=\"#served\">What is served</a></li><li><a href=\"#containment\">Execution containment</a></li><li><a href=\"#assurance\">Checking a result</a></li><li><a href=\"#chat-work\">Chat &amp; Work</a></li><li><a href=\"#access\">Accounts and access</a></li><li><a href=\"#reviews\">Security reviews</a></li><li><a href=\"#known-limits\">Scope and limitations</a></li></ol></nav></section><section id=\"seen\"><div><div><p class=\"s-k\">What we have actually seen</p><h2 id=\"seen-h\">Real requests have been paid for, end to end.</h2><p class=\"s-lede\">Each of these was established by reading the production ledger. They cover paid model requests from the public API and from Chat &amp; Work. This is alpha volume: it shows the request, billing and payout path working end to end, and says nothing about demand or behaviour under load.</p></div><div><details class=\"s-card\"><summary><h3>Requests have run from end to end</h3></summary><p>Paid requests have been admitted, run on a node, billed to the customer once and credited to one node once.</p></details><details class=\"s-card\"><summary><h3>Long inputs have been served</h3></summary><p>Requests that carried at least 32,768 input tokens have been billed and credited to an operator on the live route.</p></details><details class=\"s-card\"><summary><h3>Requests that did not complete cost nothing</h3></summary><p>Requests have been admitted and then ended without a charge, some of them after a node had already taken them.</p></details></div></div></section><section id=\"money\"><div><div><p class=\"s-k\">Price, charge and payout</p><h2 id=\"money-h\">What a request costs, and when it costs nothing.</h2><p class=\"s-lede\">This is how the live route handles money. The live route is the request path that serves <code>chat-35b-moe</code> today, for the public API and for the model turns of <span>Chat &amp; Work.</span></p></div><div><details class=\"s-card\"><summary><h3>Prices come from the release, not the request</h3></summary><p>The rates are published in the public catalog. Today <code>chat-35b-moe</code> costs $0.126 per million input tokens and $0.81 per million output tokens. The rates are built into the service and bound to its signed activation. A request cannot set a price or choose a tier. The <a href=\"/pricing\">Pricing page</a> has worked examples.</p></details><details class=\"s-card\"><summary><h3>We count the tokens ourselves</h3></summary><p>The service counts input tokens when it admits a request, and recounts the output from the text it received. A node's own count is never used to bill a customer or to pay an operator. Input is counted as the model receives it, including the chat template and any tool definitions, so it can differ from your own count.</p></details><details class=\"s-card\"><summary><h3>The worst case is reserved first</h3></summary><p>Before any work starts, the full input plus your output limit is reserved against your available prepaid balance. If you set no output limit, the reservation assumes 32,768 output tokens, or the rest of the context window if less remains. A request the balance cannot cover is refused. A balance cannot go below zero, and the final charge can never be more than the amount reserved.</p></details><details class=\"s-card\"><summary><h3>Charge and payout are saved together</h3></summary><p>When a request succeeds, one database transaction charges the actual usage, releases the rest of the reservation, writes your ledger entry and records what the operator is owed. The final result is sent only after that is saved. In a streamed request the text arrives earlier; if the request then fails on our side, you are not charged for it. The operator's pay can never exceed what you were charged for that request. If a request fails on a node after output has started, you are not charged and it is not retried.</p></details><details class=\"s-card\"><summary><h3>A request that fails on our side costs nothing</h3></summary><p>If a request fails on our side after a node has taken it, you are not charged and the node is not paid. That covers a node that crashes or disconnects, an invalid result, and a missed deadline. Each request has a deadline derived from signed minimum speeds: it is a cut-off, not a speed promise. A request that finds no free node before its queue deadline is also released at no charge. If its node fails before any output is sent, Tenvor may retry a request once on another node; the failed attempt is not charged or paid. A request that you cancel, or that stops at your own output limit, can be charged for its input and the output it generated.</p></details><details class=\"s-card\"><summary><h3>A cancelled request may cost something</h3></summary><p>Cancelling before a node has taken the request is free. After that, if the node confirms the cancel, you pay for the full input and for the output produced up to that point. If the node finishes first, you pay for the full reply. Closing a streaming connection cancels the request. Closing a non-streaming connection after a node has taken the request does not: it runs to completion and is billed.</p></details><details class=\"s-card\"><summary><h3>A repeated request needs an idempotency key</h3></summary><p>An Idempotency-Key header makes a repeated request count once, with no second charge. Without the header, every request is new and billable. Chat &amp; Work and the Playground always send one.</p></details><details class=\"s-card\"><summary><h3>A minimum charge applies</h3></summary><p>A settled request has a minimum charge of $0.000134, so a very short request is priced at that minimum and not per token.</p></details></div><p>Every settled request has a receipt showing the tokens counted and the amount charged, and for a completed request the rates. A receipt holds no request content. It is in the response to a non-streaming request. The charge also appears in your account ledger, with the amount and the request ID. A generic 503 or 504, or a dropped connection, does not tell you whether you were charged. Check your ledger.</p></div></section><section id=\"served\"><div><div><p class=\"s-k\">What is served</p><h2 id=\"served-h\">One model, with one fixed context window.</h2><p class=\"s-lede\">What the model is, and what it costs, is on the <a href=\"/models\">Models</a> and <a href=\"/pricing\">Pricing</a> pages.</p></div><div><details class=\"s-card\"><summary><h3>One model is served today</h3></summary><p><code>chat-35b-moe</code> is the only model that nodes serve. The catalog lists three other models with prices, and labels all four “available”. That label is fixed in the release. It does not mean a node is serving the model, and nothing serves those three today.</p></details><details class=\"s-card\"><summary><h3>The context window is fixed</h3></summary><p>Every node that serves <code>chat-35b-moe</code> serves its full context window, which the public catalog lists as 65,536 tokens. The size is fixed in the release. It is not chosen per node or per request. Input and output share the window, so a long prompt leaves less room for the reply. The other three catalog models are not set up for this window yet.</p></details><details class=\"s-card\"><summary><h3>A signed activation switches serving on</h3></summary><p>Serving is turned on by an activation signed with a release key. It pins the model file, the runtime image and the price policy by hash, carries the minimum speeds as signed numbers, and has an end date. The service rejects an activation that does not match its own build. When an activation ends, the live route stops admitting new requests, and requests already admitted can finish.</p></details></div></div></section><section id=\"containment\"><div><div><p class=\"s-k\">Execution containment</p><h2 id=\"containment-h\">What a node runs, and what it can see.</h2></div><div><div class=\"s-card\"><h3>The model runs in a restricted container</h3><ul><li>A rootless container runtime. The worker refuses to start the model on any other kind.</li><li>No network (<code>--network=none</code>). The worker reaches the model over a private local socket.</li><li>All capabilities dropped (<code>--cap-drop=ALL</code>), and no new privileges.</li><li>Model weights mounted read-only, and checked against a pinned SHA-256 before launch.</li><li>A runtime image pinned by content digest, never pulled at launch.</li><li>CPU, RAM and process limits requested from the container runtime, using the operator's own settings, with <code>/tmp</code> limited to 256 MB.</li><li>The container's own filesystem is writable, and is discarded when the container is removed.</li></ul><p>Rootless means the container has no root access to the machine. It still runs under the operator's own user account. All of this describes the model container. The worker program beside it does use the network, to reach the service and to download the model and the runtime image.</p></div><div><details class=\"s-card\"><summary><h3>What a node receives</h3></summary><p>A node receives the conversation, the tool definitions and the generation settings for the request it serves. It does not receive your account ID, API key, email address or IP address. The worker holds each incoming request in a private temporary file until it is assembled, then deletes the file. The file is deleted, not overwritten. A retried request is also sent to a second node, and the first node has already seen it.</p></details><details class=\"s-card\"><summary><h3>The operator can read it</h3></summary><p>The operator of a node can read the prompt and the output of every request that node serves, in plain text. There is no end-to-end encryption and no secure enclave. Operators join by invitation, and our Compute Provider Terms forbid them from copying, logging or keeping content. That protection is a contract. It is not yet a technical control.</p></details><details class=\"s-card\"><summary><h3>Requests per node</h3></summary><p>Each node serving today runs one request at a time. A node whose graphics card holds the whole model can run more than one. If every node is busy, a request waits for one to free up, up to a signed queue limit, and then fails at no charge. If no node is available at all, it is refused immediately. A retry after a node failure waits only briefly for a free node, and if none is free the request fails at no charge.</p></details><details class=\"s-card\"><summary><h3>The model's working state is erased by default</h3></summary><p>The worker erases the model's working state after each request. Erasure is a software call. We have not proven that nothing remains in memory afterwards.</p></details><details class=\"s-card\"><summary><h3>What rests on the node's own software</h3></summary><p>These protections are applied by the worker software on the operator's machine. Each node is enrolled by hand, and the worker checks the hardware and measures the model's speed before it serves. A node reports which runtime and model it runs, signed with its own key, and the service checks that report against the signed activation. Proof that does not depend on the node's own software is not built yet: there is no hardware attestation, so a modified worker could report differently.</p></details></div></div></div></section><section id=\"assurance\"><div><div><p class=\"s-k\">Checking a result</p><h2 id=\"assurance-h\">Every live request is Standard: answered by one enrolled node.</h2></div><div><div class=\"s-card\"><h3>What is checked</h3><ul><li>The result arrives signed by the node's key and bound to that exact request and attempt. Stale or replayed messages are rejected.</li><li>The structure of the reply. A tool call, for example, must name a tool the request declared.</li><li>The token counts used for billing, which come from our own tokenizer.</li><li>That the operator's pay does not exceed the customer's charge.</li><li>An overall deadline, kept on our own clock. The timings of each phase are reported by the node. The deadline is a cut-off, not a speed promise.</li></ul></div><div class=\"s-card\"><h3>What is not checked yet</h3><ul><li>Whether the answer is correct or good.</li><li>Independent proof of what a node ran. Each node is enrolled by hand and tested before it serves, and it reports its model and runtime signed with its own key. Proof that does not rely on the node's own software is not built yet.</li><li>A second node's answer. Two other tiers are priced in the catalog: Verified (two nodes run the same request and the results are compared) and Audited (one result in ten is re-run on another node afterwards). Both exist only in an older request path that does not serve <code>chat-35b-moe</code>. They cannot be bought, and a request cannot choose a tier.</li></ul></div></div></div></section><section id=\"chat-work\"><div><div><p class=\"s-k\">Chat &amp; Work</p><h2 id=\"chat-work-h\">Where a conversation goes, and who else sees part of it.</h2><p class=\"s-lede\">Model turns in Chat &amp; Work are billed like API requests, with the same receipts. The tools bring in other parties, and they sit outside the node boundary described above.</p></div><div><details class=\"s-card\"><summary><h3>Model turns go to a node</h3></summary><p>Every turn sends the conversation so far to a node. That includes web results and command output the model asked for, and in Chat the text of an attached file.</p></details><details class=\"s-card\"><summary><h3>Commands run in a third-party sandbox</h3></summary><p>When Work runs a command, it runs in a fresh cloud sandbox from E2B, a sandbox provider. It does not run on a node or on our servers. E2B receives the command, the files you selected for the run and the output. The sandbox is created with internet access off unless you turn it on. Before anything runs, our server confirms that E2B reports that setting, and stops if it does not. We have tested this against the real service once. Within a conversation the setting stays on until you switch it off. With internet on, code in the sandbox can send data out.</p></details><details class=\"s-card\"><summary><h3>Search and page reads</h3></summary><p>Web search goes to Exa, a search provider, which receives the query and no account identifier. Page reads are fetched by our own server, not by your browser. Chat and Work can both search and read pages, and there is no switch to turn that off for a run. The model writes each query and URL, so either can contain text from your conversation.</p></details><details class=\"s-card\"><summary><h3>Files and conversations</h3></summary><p>Conversations, and files a run generates, are never kept: they are erased when the request finishes.</p></details><details class=\"s-card\"><summary><h3>Limits on one task</h3></summary><p>A task stops at its spend cap or after 10 minutes, whichever comes first. The spend cap starts at $0.10 on free credit and $0.25 otherwise; you can change it in Work. One task can make up to 20 web lookups (searches and page reads together) and 30 commands of up to 60 seconds each. When a task is about to reach a limit, its last turn is sent with tools off so that it ends with an answer. A search costs what the provider charges us, and never more than the amount held for it before it starts. A command costs a fixed rate for each second it runs. The Pricing page has the usual price of a search and the rate per second.</p></details><details class=\"s-card\"><summary><h3>Accounts are kept apart</h3></summary><p>Every read and write is tied to the signed-in account. Another account's task, file or upload returns “not found”. This is covered by tests using test accounts. It has not yet been tested with two real signed-in accounts in production.</p></details><details class=\"s-card\"><summary><h3>When an outcome is unclear</h3></summary><p>If a search or command may have run and we cannot confirm what it cost, the amount stays reserved and the run is marked for review. That includes a command that overruns its time or output limit, and a search that times out. Nothing is run again. Today a person resolves these by hand, and the account cannot start another run until then.</p></details><details class=\"s-card\"><summary><h3>Web content can steer the model</h3></summary><p>Pages, search results and file contents are labelled as untrusted for the model. The model still reads them and can be influenced by them. The protection is the limits above: small caps, none of our credentials in the sandbox, and internet off by default. Even with sandbox internet off, a page that manipulates the model could make it put text from your conversation into a search query or a page address.</p></details></div></div></section><section id=\"access\"><div><div><p class=\"s-k\">Accounts and access</p><h2 id=\"access-h\">Keys, sessions and separation between accounts.</h2></div><div><details class=\"s-card\"><summary><h3>API keys</h3></summary><p>A key is 192 random bits. We store a hash of it and its last eight characters, and show the full key once. You can rotate or revoke it from the console after re-verifying your sign-in, and that takes effect immediately.</p></details><details class=\"s-card\"><summary><h3>Sign-in sessions</h3></summary><p>Browser sessions use Clerk, a sign-in provider. The service checks Clerk's signed session token on every request and holds no Clerk secret. A session revoked at Clerk keeps working until its token expires.</p></details><details class=\"s-card\"><summary><h3>Your requests are yours</h3></summary><p>Cancellation is looked up by account. Someone else's request ID returns the same “not found” as one that never existed.</p></details><details class=\"s-card\"><summary><h3>In transit</h3></summary><p>Clients reach the service over HTTPS, and nodes connect over an encrypted WebSocket. Administrative endpoints are blocked at our public web server and also need their own secret key.</p></details></div><p>To report a security problem, write to security@tenvor.io. The <a href=\"/legal/security\">security policy</a> says what is in scope and what to expect.</p></div></section><section id=\"reviews\"><div><div><p class=\"s-k\">Reviews</p><h2 id=\"reviews-h\">Security reviews</h2></div><div><details class=\"s-card\"><summary><h3>A full security review in July</h3></summary><p>A review of the whole system in July 2026 recorded 34 findings. All 34 have since been fixed or closed, and the fixes are covered by our own tests.</p></details><details class=\"s-card\"><summary><h3>Two further reviews that month</h3></summary><p>Reviews of money handling and of the codebase recorded 23 findings. All 23 are fixed, and the fixes have been run in field tests on real machines. Reviews by outside organizations have not happened yet.</p></details><details class=\"s-card\"><summary><h3>Chat &amp; Work review, 29 September 2026</h3></summary><p>Its main open findings are three medium issues: one credential shared between our own services is not yet separated per account; the third-party sandbox's isolation needs wider testing; and Chat &amp; Work state lives on one server.</p></details><details class=\"s-card\"><summary><h3>Review of the live route, 2 October 2026</h3></summary><p>The July reviews covered an older request path. The route that serves chat-35b-moe was built afterwards. A code review on 2 October 2026 read it as an invited tester would attack it. It did not find a way to act as another account, read another account's data, run code on our servers or on a node, or change a price or a balance. It also found lower-severity availability and billing-abuse issues.</p></details><details class=\"s-card\"><summary><h3>Who did the reviewing</h3></summary><p>Reviews are performed internally. Third-party assessments have not been completed to date.</p></details></div></div></section><section id=\"known-limits\"><div><div><p class=\"s-k\">Scope and limitations</p><h2 id=\"known-limits-h\">Scope and limitations</h2></div><div><details class=\"s-card\"><summary><h3>Internal reports are confidential</h3></summary><p>The reports and trackers behind this page are kept in a private repository.</p></details><details class=\"s-card\"><summary><h3>A small alpha</h3></summary><p>Capacity is limited. Behaviour at larger scale has not been shown in production.</p></details><details class=\"s-card\"><summary><h3>One model is served</h3></summary><p>Only chat-35b-moe is served. The other three catalog models are listed with prices, but nothing serves them today.</p></details><details class=\"s-card\"><summary><h3>A Standard result is one node’s output</h3></summary><p>A result is not yet compared with a second node’s. The Verified and Audited tiers that do this exist only in an older request path that does not serve chat-35b-moe. They are priced in the catalog but cannot be bought.</p></details><details class=\"s-card\"><summary><h3>Operators can read what they process</h3></summary><p>A node sees the prompts and outputs of the requests it serves, in plain text. A retried request is also sent to a second node, and the first node has already seen it.</p></details><details class=\"s-card\"><summary><h3>A retry is not a promise</h3></summary><p>A retry is not a promise that the request completes. It takes extra time, and it needs a second node that is free soon. A request is retried at most once, and never after you cancel it. A stream that fails after output has started is not retried, and Tenvor does not resume it.</p></details><details class=\"s-card\"><summary><h3>Containment is not yet checked remotely</h3></summary><p>The container limits are applied by the worker on the operator’s machine, and the worker reports its hardware and runtime to the service. Checking them from outside, without relying on the node’s own software, is being worked on.</p></details><details class=\"s-card\"><summary><h3>Third-party assessments</h3></summary><p>Security statements on this page are based on internal reviews and testing. Third-party assessments have not been completed to date.</p></details><details class=\"s-card\"><summary><h3>Nothing is retained</h3></summary><p>Requests are never logged or kept. A request's content and files are erased when it finishes.</p></details><details class=\"s-card\"><summary><h3>Cached input is not guaranteed</h3></summary><p>Cached input costs half the input price, and only a request that asks for reuse can get it; a plain OpenAI client asks for none. Reuse is never guaranteed.</p></details><details class=\"s-card\"><summary><h3>One request at a time on today’s nodes</h3></summary><p>Each node serving today runs one request at a time. A node whose graphics card holds the whole model can run more than one.</p></details><details class=\"s-card\"><summary><h3>No load test</h3></summary><p>The public API has not established sustained demand, queueing behaviour, or latency percentiles under load. There is no controlled simultaneous-request dataset for the route serving today.</p></details><details class=\"s-card\"><summary><h3>No speed figure is published</h3></summary><p>Tenvor has not published a speed figure for the build that serves today. Speed also drops in long conversations.</p></details><details class=\"s-card\"><summary><h3>No uptime or latency SLA</h3></summary><p>Availability is alpha capacity, not a service commitment. There is no public incident feed yet. The status page says how incidents are reported.</p></details></div><div><a class=\"s-btn\" href=\"/status\">Read the status page</a></div></div></section><section id=\"contact-security\" class=\"tc-cta\"><div><h2 class=\"tc-h\">Talk to us about security.</h2><p>Questions about this page, or a problem to report.</p></div><div class=\"s-row\"><a class=\"s-btn s-btn--accent\" href=\"mailto:security@tenvor.io\">security@tenvor.io</a><a class=\"s-btn\" href=\"/contact\">Contact</a></div></section><section id=\"legal-notice\" class=\"tc-legal\"><p class=\"s-k\">Legal notice</p><p>This page describes Tenvor’s security practices as of November 2026 and is provided for information only. It does not form part of, or change, any agreement. Your use of Tenvor is governed by our <a href=\"/legal/terms\">Terms of Service</a>, <a href=\"/legal/acceptable-use\">Acceptable Use Policy</a> and <a href=\"/legal/privacy\">Privacy Policy</a>. No method of transmission or storage is completely secure, and Tenvor does not guarantee absolute security. Our controls may change as the service evolves. During the public alpha the service is provided “as is”, as described in the <a href=\"/legal/public-alpha-risk\">Public Alpha Risk</a> notice.</p><p>Report vulnerabilities to <a href=\"mailto:security@tenvor.io\">security@tenvor.io</a> under our <a href=\"/legal/security\">Security Policy</a>. Do not access other users’ data or disrupt the service while testing.</p></section></div>"
};
export default page;
